/**
 * ═══════════════════════════════════════════════════════════════════════════
 * MOBILE DRAFT STEPS CACHE
 * ═══════════════════════════════════════════════════════════════════════════
 *
 * In-memory cache for draft mobile-test steps generated by mobile_agent.
 * Mirror of `DraftStepsCache` (web) — same TTL, same key, same patterns.
 *
 * Why a separate cache instead of reusing the web one:
 *   - Mobile uses MobileIntentStep[] (different shape from web's IntentStep[]).
 *     Sharing one Map would either require a union type (loose) or runtime
 *     discrimination per entry. A separate module keeps both type-safe.
 *   - Mobile cache holds `mobileSessionId` + optional `appPackage` /
 *     `startActivity` — fields that have no counterpart in web's startUrl.
 *
 * Keyed by chatSessionId, NOT mobileSessionId, because:
 *   - The chat session persists across runner-session restarts.
 *   - "Show me the plan" → "Run it" → "Save it" can span 5-10 minutes; the
 *     runner session may have been recycled.
 *
 * ═══════════════════════════════════════════════════════════════════════════
 */

import type { MobileIntentStep, MobilePlatform } from '@/services/mobile/mobile-runner.types';
import { logger } from '@/utils/core/logger';

interface CachedMobileDraftSteps {
  steps: MobileIntentStep[];
  /** Runner session the draft was authored against (advisory; replay reuses platform metadata). */
  mobileSessionId: string;
  platform: MobilePlatform;
  appPackage?: string;
  startActivity?: string;
  createdAt: number;
  userId: string;
  /** Suggested name for `mobile_create_test_case` to default to. */
  suggestedName?: string;
}

/** Match web cache: 30 minutes. Long enough for plan → run → save spans. */
const DRAFT_CACHE_TTL_MS = 30 * 60 * 1000;

/** Lazy-cleanup threshold — mirror web. */
const CLEANUP_THRESHOLD = 50;

/** Module-scoped. Single Node process per environment — see web cache jsdoc. */
const cache = new Map<string, CachedMobileDraftSteps>();

export const MobileDraftStepsCache = {
  set(chatSessionId: string, data: Omit<CachedMobileDraftSteps, 'createdAt'>): void {
    cache.set(chatSessionId, { ...data, createdAt: Date.now() });

    if (cache.size > CLEANUP_THRESHOLD) {
      const now = Date.now();
      for (const [key, entry] of cache) {
        if (now - entry.createdAt > DRAFT_CACHE_TTL_MS) {
          cache.delete(key);
        }
      }
    }

    logger.debug('[MOBILE_DRAFT_STEPS_CACHE] Cached', {
      chatSessionId,
      stepCount: data.steps.length,
      platform: data.platform,
    });
  },

  get(chatSessionId: string): CachedMobileDraftSteps | undefined {
    const entry = cache.get(chatSessionId);
    if (!entry) return undefined;
    if (Date.now() - entry.createdAt > DRAFT_CACHE_TTL_MS) {
      cache.delete(chatSessionId);
      logger.debug('[MOBILE_DRAFT_STEPS_CACHE] Entry expired', { chatSessionId });
      return undefined;
    }
    return entry;
  },

  delete(chatSessionId: string): boolean {
    const deleted = cache.delete(chatSessionId);
    if (deleted) logger.debug('[MOBILE_DRAFT_STEPS_CACHE] Entry cleared', { chatSessionId });
    return deleted;
  },

  /**
   * Atomic read-and-delete — same race-defence rationale as web cache:
   * two concurrent save calls would otherwise both insert into
   * intent_test_cases.
   */
  consume(chatSessionId: string): CachedMobileDraftSteps | undefined {
    const entry = cache.get(chatSessionId);
    if (!entry) return undefined;
    if (Date.now() - entry.createdAt > DRAFT_CACHE_TTL_MS) {
      cache.delete(chatSessionId);
      logger.debug('[MOBILE_DRAFT_STEPS_CACHE] Entry expired on consume', { chatSessionId });
      return undefined;
    }
    cache.delete(chatSessionId);
    logger.debug('[MOBILE_DRAFT_STEPS_CACHE] Entry consumed', { chatSessionId });
    return entry;
  },

  /** @internal TEST-ONLY */
  __dangerousClearForTests(): void {
    cache.clear();
  },
};
